	private void selectorDefaultAliasWithDataset(RepositoryConnection conn) {
		seedAlias(conn);
		for (IRI alias : List.of(RDF4J.NIL, SESAME.NIL)) {
			// dataset naming the alias: the enumerated alias is the dataset's default-graph data
			SimpleDataset including = new SimpleDataset();
			including.addNamedGraph(alias);
			TupleQuery q = conn.prepareTupleQuery(PREFIX + "SELECT ?s ?o { VALUES ?g { <" + alias
					+ "> } GRAPH ?g { ?s :p ?o } }");
			q.setDataset(including);
			assertRows(q, names("s", "o"), bag(r("s", "ds", "o", "do")),
					"FROM NAMED alias, VALUES selects alias " + alias);

			TupleQuery twoRows = conn.prepareTupleQuery(PREFIX + "SELECT ?k ?s ?o { VALUES ?k { 1 2 } VALUES ?g { <"
					+ alias + "> } GRAPH ?g { ?s :p ?o } }");
			twoRows.setDataset(including);
			assertRows(twoRows, names("k", "s", "o"),
					bag(r("k", num(1), "s", "ds", "o", "do"), r("k", num(2), "s", "ds", "o", "do")),
					"FROM NAMED alias with two sibling VALUES " + alias);

			// dataset excluding the alias: not a member of the enumeration domain
			SimpleDataset excluding = new SimpleDataset();
			excluding.addNamedGraph(iri("g1"));
			TupleQuery ex = conn.prepareTupleQuery(PREFIX + "SELECT ?g ?s ?o { VALUES ?g { <" + alias
					+ "> :g1 } GRAPH ?g { ?s :p ?o } }");
			ex.setDataset(excluding);
			assertRows(ex, names("g", "s", "o"), bag(r("g", "g1", "s", "a", "o", "o1")),
					"FROM NAMED excluding alias " + alias);

			// dataset naming both
			SimpleDataset both = new SimpleDataset();
			both.addNamedGraph(alias);
			both.addNamedGraph(iri("g1"));
			TupleQuery bq = conn.prepareTupleQuery(PREFIX + "SELECT ?g ?s ?o { VALUES ?g { <" + alias
					+ "> :g1 } GRAPH ?g { ?s :p ?o } }");
			bq.setDataset(both);
			assertRows(bq, names("g", "s", "o"),
					bag(r("g", alias, "s", "ds", "o", "do"), r("g", "g1", "s", "a", "o", "o1")),
					"FROM NAMED including alias and g1 " + alias);
		}
	}

